ne-height:1.6;border:1px solid #962c2966;padding:12px}.product-availability-link{display:block;font-size:11px;margin:15px auto;text-underline-offset:4px}.product-tax-note{font-size:9px;letter-spacing:.7px;text-transform:uppercase;margin:30px 0 45px;line-height:1.6}.product-tax-note a{text-underline-offset:3px}.product-accordions{margin-top:48px;text-align:left}.product-accordion{border-top:1px solid var(--color-line)}.product-accordion:last-child{border-bottom:1px solid var(--color-line)}.product-accordion summary{cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;padding:16px 12px;font-size:9px}.product-accordion summary::-webkit-details-marker{display:none}.product-accordion summary>span{font-size:17px;font-weight:300}.product-accordion[open] summary>span{transform:rotate(45deg)}.product-accordion>.rte{font-size:12px;line-height:1.8;padding:0 12px 12px}.product-content-block{padding:24px 0;font-size:12px}.product-gallery{background:#fff}.product-gallery__viewport{position:relative;display:flex;gap:0;width:100%;height:clamp(360px,calc(100svh - var(--header-height,80px) - 61px),900px);overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;overscroll-behavior-x:contain}.product-gallery__viewport::-webkit-scrollbar{display:none}.product-gallery__viewport:focus-visible{outline-offset:-3px}.product-gallery__item{position:relative;flex:0 0 100%;min-width:0;min-height:0;scroll-snap-align:start;background:#fff}.product-gallery__zoom{display:block;position:relative;height:100%;cursor:zoom-in}.product-gallery__zoom:focus-visible{outline-offset:-3px}.product-gallery__zoom>img{display:block;width:100%;height:100%;aspect-ratio:auto;object-fit:contain;background:#fff}.product-gallery__zoom-label{position:absolute;bottom:20px;left:20px;right:20px;display:flex;justify-content:space-between;font-size:9px;text-transform:uppercase;letter-spacing:1px;opacity:0;transition:opacity .2s}.product-gallery__zoom:hover .product-gallery__zoo